import{a as e,n as t,r as n}from"./index-elP0lDxp.js";var r={class:`markdown-body`},i={__name:`about_app`,setup(i,{expose:a}){return a({frontmatter:{}}),(i,a)=>(e(),t(`div`,r,[...a[0]||=[n(`<h1>About This App</h1><p>A lightweight and fast cross-section properties calculator for structural mechanics engineers. It runs entirely in your browser.</p><h2>What you can do</h2><ul><li><strong>Use basic shapes:</strong> rectangle, hollow rectangle, tube, and I, C, T, L and Z shapes.</li><li><strong>Define your own shape:</strong> click its points on the canvas or import them from a CSV file, then fine-tune the coordinates by typing them in.</li><li><strong>Build up a section:</strong> combine several shapes. Mark a shape as negative to cut a hole.</li><li><strong>Print the results:</strong> open <code>File</code> → <code>Show Results</code> for a report you can print or save as a PDF.</li><li><strong>Save your work:</strong> export a project and import it again later.</li></ul><h2>What it calculates</h2><p>Area, centroid, moments of inertia, principal axes, polar moment, radii of gyration and section moduli. Lengths are in mm and angles in degrees.</p><h2>Algorithms used</h2><table><thead><tr><th>Shape</th><th>Method</th></tr></thead><tbody><tr><td>Tube</td><td>Standard formulas</td></tr><tr><td>Other basic shapes</td><td>Green’s theorem</td></tr><tr><td>Custom shape</td><td>FEM mesh</td></tr><tr><td>Whole section</td><td>Combined from its shapes with the parallel axis theorem</td></tr></tbody></table><h2>Good to know</h2><ul><li>Torsion and shear properties are not calculated yet.</li><li>Shapes are not clipped against each other, so the layout is up to you. A negative shape must lie fully inside the positive shapes, and negative shapes must not overlap. Otherwise the results can be wrong without any warning.</li><li>Overlapping positive shapes are counted twice. A cut-out that removes a whole outer strip makes the section modulus on that side too small.</li></ul>`,10)]]))}};export{i as default};